#pragma once
// Independent double-precision glTF reference. No native Skeleton matrices,
// skinning helper or automatic-weight code is used to evaluate artist geometry.
#include "cgltf.h"
#include <nlohmann/json.hpp>
#include <array>
#include <vector>
#include <map>
#include <set>
